var oAuthClient = new sn_auth.GlideOAuthClient();

var params = {grant_type:"refresh_token", refresh_token:'VnV12i58ahMRQe5MOSIhdYYqVdab9J1xrWKcbNs4hTSBOzqwH07H7ca3tmfkl5AFVmoGtMLycT58EvOQqHUoLw'}; //
